# ====================== v412 -- a camada cientifica e a matematica que restava: 40 modulos novos de TGLExt/ (903 bandeiras, a escada 12308 -> 13211), a guarda de frases da v412, a secao “O que fica claro na v412” do artigo e quatro registros por especificacao (iald_camada_cientifica_v412, matematica_que_restava_v412, parede_do_teste_cego_v412, cunhagens_v412).
# Os registros usam o motor da v392 (_v392_registro); nenhum tem funcao nova; nenhuma chave antiga muda; validade no kernel nao e' creditacao; o gate nao se move.
def _v412_guarda_frases(txt_):
    """v412 -- a guarda das frases: herda a da v411 (_v411_guarda_frases, que herda as anteriores) e muda tres obrigacoes, nos textos que a v412 escreve.
    (1) P = nP (as regras F34 e F37 herdadas): onde aparece “P = nP”, a obrigacao fica satisfeita tambem quando a mesma unidade de texto traz as duas marcas do paragrafo vigente:
        “classes do seu dicionario” (EN: classes of its dictionary) e a ressalva da maquina de fita, “maquina de fita” seguida, na mesma frase, de “nao esta demonstrado” (EN: tape machine ... has not been shown).
        A forma antiga segue aceita nos textos herdados; as regras que proibem afirmar que a TGL prova ou decide P = NP das maquinas de Turing seguem como estavam.
    (2) as formas da F43 (oraculo, leitor de Turing, leitor que devolve Z) seguem como estavam: a guarda nao muda por causa delas.
    (3) o nome do problema dos fluidos: F68a so' aparece em unidade que traga a forma condicional (“condicional”, “condicionada”) ou a negacao expressa (“nao diz que” antes do nome, na mesma oracao);
        F68b “resolve”, “prova”, “solucao” e “demonstrada” afirmados na mesma oracao do nome sao recusados; F69 o nome do premio e' vedado em todo texto.
    Devolve [(regra, trecho)]."""
    import re as _re
    s_ = str(txt_)
    marca_dic_ = bool(_re.search(r"classes\s+do\s+seu\s+dicion(?:á|a)rio|classes\s+of\s+its\s+dictionary", s_, _re.I))
    marca_fita_ = bool(_re.search(r"m(?:á|a)quina\s+de\s+fita[^.;\n]{0,300}?n(?:ã|a)o\s+est(?:á|a)\s+demonstrad|tape\s+machine[^.;\n]{0,300}?has\s+not\s+been\s+shown", s_, _re.I))
    vigente_ = marca_dic_ and marca_fita_
    out_ = [v_ for v_ in _v411_guarda_frases(txt_) if not (vigente_ and (v_[0].startswith("F34_") or v_[0].startswith("F37_")))]
    _NOME_FLUIDOS_ = _re.compile(r"Navier\s*(?:[–—-]{1,2}|\\textendash(?:\{\})?)?\s*Stokes|Stokes\s*(?:[–—-]{1,2}|\\textendash(?:\{\})?)?\s*Navier", _re.I)
    _COND_ = _re.compile(r"\bcondicional\b|\bcondicionad[ao]s?\b|\bconditional\b|\bconditioned\b", _re.I)
    _NEGEXP_ = _re.compile(r"n(?:ã|a)o\s+diz\s+que|does\s+not\s+say\s+that|do\s+not\s+say\s+that|doesn't\s+say\s+that", _re.I)
    _AFIRMA_ = _re.compile(r"\bresolv(?:e|eu|emos|ido|ida|idos|idas|endo)\b|\bprova(?:d[ao]s?|mos|u|m)?\b|\bsolu(?:ç|c)(?:ã|a)o\b|\bdemonstrad[ao]s?\b|\bsolved?\b|\bsolves\b|\bresolve[sd]?\b|\bproves?\b|\bproved\b|\bproven\b|\bsolution\b|\bdemonstrated\b", _re.I)
    _NEG_ = _re.compile(r"\bn(?:ã|a)o\b|\bnunca\b|\bnem\b|\bsem\b|\bnot\b|\bnever\b|\bno\b|\bnor\b|\bwithout\b|n't\b", _re.I)
    blocos_ = [b_ for b_ in _re.split(r"\n\s*\n|\"\s*,\s*\"|\\n\\n|\"\s*:\s*\"|\"\s*\]|\[\s*\"", s_) if b_.strip()]
    for seg_ in blocos_:
        for m_ in _NOME_FLUIDOS_.finditer(seg_):
            ini_ = max(seg_.rfind(c_, 0, m_.start()) for c_ in (".", ";", ":", "\n"))
            fim_ = [i_ for i_ in (seg_.find(c_, m_.end()) for c_ in (".", ";", ":", "\n")) if i_ >= 0]
            oracao_ = seg_[ini_ + 1:(min(fim_) if fim_ else len(seg_))]
            antes_ = seg_[ini_ + 1:m_.start()]
            if not (_COND_.search(seg_) or _NEGEXP_.search(antes_)):
                out_.append(("F68a_o_nome_dos_fluidos_sem_a_forma_condicional_ou_a_negacao_expressa", seg_[max(0, m_.start() - 40):m_.end() + 60].strip()[:200]))
            for a_ in _AFIRMA_.finditer(oracao_):
                if not _NEG_.search(oracao_[max(0, a_.start() - 100):a_.start()]):
                    out_.append(("F68b_resolucao_afirmada_junto_do_nome_dos_fluidos", oracao_.strip()[:200]))
                    break
    for m_ in _re.finditer(r"\bmil[eê]nio\b|\bmillennium\b", s_, _re.I):
        out_.append(("F69_o_nome_do_premio", s_[max(0, m_.start() - 30):m_.end() + 30].replace("\n", " ")))
    return out_


def _v412_secao_tex(lang_):
    """v412 -- a secao “O que fica claro na v412” do artigo, em 'pt' ou 'en': texto da teoria montado da pagina publica, sem numero do core (os numeros do kernel estao nos registros); devolve a lista de linhas para s.append."""
    return list(_V412_SECAO[lang_])


def _v412_rodar_specs(core_):
    """v412 -- roda os quatro registros por especificacao da v412 (o motor e' o da v392: _v392_registro), na ordem de _V412_SPECS (cunhagens_v412 por ultimo: cobra o selo dos outros tres);
    excecao vira AVISO visivel (all_verified False), nunca derruba o rito."""
    for spec_ in _V412_SPECS:
        try:
            core_[spec_["nome"]] = _v392_registro(spec_, core_)
        except Exception as e_:   # noqa: BLE001
            core_[spec_["nome"]] = {"verdict": "%s__NOT_RECORDED_THIS_RUN__RUNTIME_ERROR__GATE_UNMOVED" % spec_["veredito_prefixo"], "all_verified": False, "error": repr(e_)[:400], "does_not_gate_core": True}
    return [s_["nome"] for s_ in _V412_SPECS]


