        'máquina de fita com custo polinomial não está demonstrada.',
        '\\subsection*{3. Navier–Stokes, como resultado condicional}',
        '\\begin{quote}Para dados inicialmente em H$^s$, a cascata diádica represada propaga essa regularidade quando $\\tau$ > ln 2. Para a equação de '
